from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    k = len(alphabet)
    if not banned:
        return pow(k, n, MOD)

    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}
    children: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for word in banned:
        u = 0
        for ch in word:
            c = char_to_idx[ch]
            nxt = children[u][c]
            if nxt == -1:
                nxt = len(children)
                children[u][c] = nxt
                children.append([-1] * k)
                bad.append(False)
            u = nxt
        bad[u] = True

    fail = [0] * len(children)
    queue: deque[int] = deque()
    for c in range(k):
        v = children[0][c]
        if v != -1:
            fail[v] = 0
            queue.append(v)
        else:
            children[0][c] = 0

    while queue:
        u = queue.popleft()
        f = fail[u]
        if bad[f]:
            bad[u] = True
        for c in range(k):
            v = children[u][c]
            if v != -1:
                fail[v] = children[f][c]
                if bad[u]:
                    bad[v] = True
                queue.append(v)
            else:
                children[u][c] = children[f][c]

    state_id = [-1] * len(children)
    m = 0
    for u in range(len(children)):
        if not bad[u]:
            state_id[u] = m
            m += 1

    mat = [[0] * m for _ in range(m)]
    for u in range(len(children)):
        su = state_id[u]
        if su != -1:
            row = mat[su]
            for nxt in children[u]:
                sv = state_id[nxt]
                if sv != -1:
                    row[sv] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ri = res[i]
            for t in range(m):
                val = ai[t]
                if val:
                    bt = b[t]
                    for j in range(m):
                        ri[j] += val * bt[j]
            for j in range(m):
                ri[j] %= MOD
        return res

    def vec_mat_mul(v: list[int], b: list[list[int]]) -> list[int]:
        res = [0] * m
        for t in range(m):
            vt = v[t]
            if vt:
                bt = b[t]
                for j in range(m):
                    res[j] += vt * bt[j]
        return [x % MOD for x in res]

    vec = [0] * m
    vec[0] = 1
    exp = n
    while exp > 0:
        if exp & 1:
            vec = vec_mat_mul(vec, mat)
        exp >>= 1
        if exp > 0:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
